var a=[{title:`Cât de complex este un exercițiu`,text:`Un ramat sprijinit la aparat se mișcă pe un traseu stabil. Un îndreptat românesc pe un picior cere echilibru, controlul trunchiului și coordonarea șoldului, iar un swing cu kettlebell adaugă viteză și sincronizare. Poți fi foarte puternic și totuși nou la una dintre aceste îndemânări.`},{title:`Mergi de la previzibil la provocator`,text:`Începe cu poziții stabile și repetări mai lente și învață câte o singură îndemânare nouă odată. Apoi fă exercițiul mai greu eliminând sprijinul, schimbând pârghia, mărind amplitudinea sau adăugând viteză controlată. O progresie ar trebui să păstreze scopul mișcării și să evite schimbarea tuturor cerințelor deodată.`},{title:`Oboseala schimbă coordonarea`,text:`Un exercițiu pe care l-ai făcut bine la începutul unei sesiuni poate deveni nesigur după multe repetări. Fă exercițiile care cer multă îndemânare mai devreme, odihnește-te mai mult când ai nevoie și încheie o serie când echilibrul sau controlul scapă. Exercițiile balistice complexe sunt de obicei o alegere slabă pentru un începător obosit.`},{title:`Exemplu`,text:`Dacă înveți fandările, poți începe cu genuflexiuni cu picioarele decalate ținându-te de o balustradă, apoi poți trece la fandări înapoi fără sprijin și poți încerca fandările în mers mai târziu. O variantă mai rapidă nu este automat mai bună.`},{title:`Folosirea TrainUp`,text:`Când TrainUp îți construiește planul, alege exerciții care se potrivesc cu nivelul și coordonarea ta, precum și cu limitările și echipamentul tău.`}];var t=[{label:`Declarația de poziție ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`Ghid practic ACSM 2026`,url:`https://www.acsm.org/wp-content/uploads/2026/03/Resistance-Training-Position-Stand-infographic.pdf`}];var r={sections:a,sources:t};export{r as default,a as sections,t as sources};